package functions

import (
	"fmt"
	"io"
	"log"

	functionrpc "github.com/azure/azure-functions-golang-worker/proto"
)

// WorkerServer implements the FunctionRpcServer interface generated by protoc.
type WorkerServer struct {
	// Embed the unimplemented server to satisfy newer versions of the gRPC code generator.
	functionrpc.UnimplementedFunctionRpcServer

	dispatcher *Dispatcher
}

// NewWorkerServer constructs a new WorkerServer.
func NewWorkerServer(dispatcher *Dispatcher) *WorkerServer {
	return &WorkerServer{
		dispatcher: dispatcher,
	}
}

